package android.graphics; public class PathMeasure {Path p;public PathMeasure(Path p,boolean close){setPath(p,close);}public void setPath(Path p,boolean close){this.p=p;}public float getLength(){float n=0;for(int i=1;i<p.pts.size();i++){float[] a=p.pts.get(i-1),b=p.pts.get(i);n+=(float)Math.hypot(b[0]-a[0],b[1]-a[1]);}return n;}public boolean nextContour(){return false;}public boolean getPosTan(float d,float[] pos,float[] tan){float[] a=p.pts.get(0);for(int i=1;i<p.pts.size();i++){float[] b=p.pts.get(i);float n=(float)Math.hypot(b[0]-a[0],b[1]-a[1]);if(d<=n){float t=n==0?0:d/n;pos[0]=a[0]+t*(b[0]-a[0]);pos[1]=a[1]+t*(b[1]-a[1]);return true;}d-=n;a=b;}pos[0]=a[0];pos[1]=a[1];return true;}}
